import sys

def solve():
    # Read all lines from standard input
    lines = []
    try:
        # Reading line by line to handle potential whitespace issues
        for _ in range(8):
            line = sys.stdin.readline().strip()
            if not line:
                break
            lines.append(line)
    except EOFError:
        pass

    # If we didn't get 8 lines, it might be an issue, but constraints say there are 8 strings.
    # Let's ensure we have the grid data.
    if len(lines) < 8:
        return 

    grid = lines

    # Initialize a set to keep track of squares that are "unsafe" (can be captured).
    unsafe_squares = set()

    # Iterate through each existing piece '#' in the grid
    for r in range(8):
        for c in range(8):
            if grid[r][c] == '#':
                # If there is a piece at (r, c), then any square in row r or column c 
                # is unsafe for placing our new piece because this piece can capture along its row and column.
                # Note: The problem says "Placed on a square in row i" OR "Placed on a square in column j".
                # This implies that if we place our piece anywhere in row 'r', the existing piece at (r,c) captures it.
                # Similarly for column 'c'.

                # Mark all empty squares in row r as unsafe
                for col_idx in range(8):
                    unsafe_squares.add((r, col_idx))

                # Mark all empty squares in column c as unsafe
                for row_idx in range(8):
                    unsafe_squares.add((row_idx, c))

    # Count how many squares are NOT in the unsafe set AND are currently empty
    count = 0
    for r in range(8):
        for c in range(8):
            if grid[r][c] == '.' and (r, c) not in unsafe_squares:
                count += 1

    print(count)

