class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # If any element is strictly less than k, it's impossible to make all elements equal to k
        # because operations only allow reducing values, not increasing them.
        if any(x < k for x in nums):
            return -1

        # Count the number of distinct values strictly greater than k.
        # Each such distinct value requires one operation to reduce it to the next level,
        # and the final step to k is included in this count.
        distinct_greater = sorted(set(x for x in nums if x > k))
        return len(distinct_greater)

