            for dst, rate in graph1[src].items():
                adj1[currency_to_idx[src]][currency_to_idx[dst]] = rate

        adj2 = [[0.0] * n for _ in range(n)]
        for src in graph2:
            for dst, rate in graph2[src].items():
                adj2[currency_to_idx[src]][currency_to_idx[dst]] = rate

