        # dp1[c] = max amount of currency 'c' after day 1 conversions starting from initialCurrency (1.0)
        dp1 = [0.0] * n
        dp1[currency_to_idx[initialCurrency]] = 1.0

        # Propagate through day 1
        # Since there are no cycles, we can use topological sort or simply iterate until no changes
        # But given constraints (n <= 1 + 2*10 = 21), we can use Bellman-Ford style relaxation multiple times
        # Or even BFS since it's a DAG? Actually, the problem says "no contradictions or cycles", so it's a DAG.
        # However, note: "no contradictions or cycles in the conversion graphs for either day" -> DAG

        # We'll use Kahn's algorithm (topological sort) or just iterative relaxation since n is small
        # Let's do iterative relaxation for simplicity and correctness

        changed = True
        while changed:
