class Solution:
    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        # Sort the unique elements
        unique_nums = sorted(set(nums))

        if not unique_nums:
            return 0

        # Start with the count as the number of unique elements
        count = len(unique_nums)

        # Iterate through the sorted unique elements to find mergeable pairs
        for i in range(len(unique_nums) - 1):
            # Check if the current element and the next can be merged
            # They can be merged if the gap between them is <= 2*k
            if unique_nums[i+1] - unique_nums[i] <= 2 * k:
                count -= 1

        return count

