class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        MOD = 10**9 + 7

        # dp[i][j] will store a dictionary where key is the XOR value of paths from (0,0) to (i,j)
        # and value is the count of such paths.
        # Initialize with the starting cell (0,0)
        dp = [[{} for _ in range(n)] for _ in range(m)]

        # Base case: starting position
        start_val = grid[0][0]
        dp[0][0][start_val] = 1

        # Iterate through each cell
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue

                current_xors = {}

                # Check possible previous cells: top (i-1, j) and left (i, j-1)
                prev_top = None if i == 0 else dp[i-1][j]
                prev_left = None if j == 0 else dp[i][j-1]

                # From top
                if prev_top:
                    for xor_val, count in prev_top.items():
                        new_xor = xor_val ^ grid[i][j]
                        current_xors[new_xor] = (current_xors.get(new_xor, 0) + count) % MOD

                # From left
                if prev_left:
                    for xor_val, count in prev_left.items():
                        new_xor = xor_val ^ grid[i][j]
                        current_xors[new_xor] = (current_xors.get(new_xor, 0) + count) % MOD

                dp[i][j] = current_xors

        return dp[m-1][n-1].get(k, 0)

class Solution:
    def maxLength(self, nums: List[int]) -> int:
        n = len(nums)
        max_len = 0

        # Since the constraints are small (nums.length <= 100), 
        # we can iterate over all possible subarrays.
        for i in range(n):
            current_prod = 1
            current_gcd = nums[i]
            current_lcm = nums[i]

            for j in range(i, n):
                num = nums[j]

                # Update product
                current_prod *= num

                # Update GCD and LCM
                # gcd(a, b, c) = gcd(gcd(a, b), c)
                # lcm(a, b, c) = lcm(lcm(a, b), c)
                new_gcd_val = self.gcd(current_gcd, num)
                if new_gcd_val == 0:
                    # Should not happen with positive integers, but safe guard
                    current_gcd = 0
                else:
                    current_gcd = new_gcd_val

                new_lcm_val = self.lcm(current_lcm, num)
                current_lcm = new_lcm_val

                # Check condition: prod == lcm * gcd
                # Note: We need to handle potential overflow or large numbers?
                # Constraints say nums[i] <= 10 and length <= 100. 
                # Max product could be 10^100 which is too large for standard types in some languages,
                # but Python handles arbitrarily large integers automatically.

                if current_prod == current_lcm * current_gcd:
                    if j - i + 1 > max_len:
                        max_len = j - i + 1

        return max_len

    @staticmethod
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    @staticmethod
    def lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // gcd(a, b)

