class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i][d] stores the max length of a subsequence ending at index i with last difference d
        # Initialize with 1 (the element itself)
        dp = [[1] * 301 for _ in range(n)]

        for i in range(n):
            # Compute suffix max for row i: s_max[d] = max(dp[i][d:])
            # This allows us to quickly find the max length of a subsequence ending at i
            # with a last difference >= d.
            s_max = [0] * 301
            curr_max = 1
            for d in range(300, -1, -1):
                if dp[i][d] > curr_max:
                    curr_max = dp[i][d]
                s_max[d] = curr_max

            # Update subsequent elements j > i
            for j in range(i + 1, n):
                d = abs(nums[i] - nums[j])
                # Since values are in [1, 300], d will be at most 299.
                if d <= 300:
                    new_len = s_max[d] + 1
                    if new_len > dp[j][d]:
                        dp[j][d] = new_len

        max_len = 1
        for i in range(n):
            for d in range(301):
                if dp[i][d] > max_len:
                    max_len = dp[i][d]

        return max_len
